	// Revoking a missing identity is NOT_FOUND.
	recorder = h.request(http.MethodDelete, "/subjects/user-1/bindings/ghost",
		map[string]any{"effectiveFrom": "2026-02-01T00:00:00Z"})
	h.mustStatus(recorder, http.StatusNotFound)
